quests[43925] = { id = 43925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runescale Koi", progress = "Have you brought us supplies?", completion = "Good work, {name}.\n\nThese supplies are crucial to crafting the elixirs we will need for the upcoming battle." }
quests[43926] = { id = 43926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion: The Legion Returns", description = "Warriors of da Horde! Break out ya axes and sharpen ya spears. Da Burning Legion has returned ta our world!\n\nWe be shipping outta Bladefist Bay right away. With da full fury of da Horde, we gonna smash der line so hard dat Sargeras is gonna feel it in da Nether!\n\nGet to da ships. We got demons ta slay!", completion = "The ships are leaving from the dock in Bladefist Bay.\n\nBefore you leave, prepare yourself. I have the feeling that this fight won't be an easy one.", objectives = "Check in with Holgar Stormaxe at the Dranosh'ar Blockade.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43928] = { id = 43928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggregates of Anguish", description = "Our preparations for conjuring the Steeds of the Damned are nearly complete.\n\nSalanar the Horseman has given us a list of the remaining components. The ritual of conjuring requires five unholy essences known as the Aggregates of Anguish.\n\nI have taken it upon myself to organize the necessary missions to obtain these components.\n\nUse the mission table to assign your chosen champions to the task.", completion = "With the Aggregates of Anguish procured, our work is nearly complete. Soon, the Steeds of the Damned will rise... and the Burning Legion will fall!", objectives = "Complete 5 \"Unholy Attainment\" missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43929] = { id = 43929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vantus Mastery", objectives = "Greetings, {name}.\n\nIt is my understanding that you have been one of the foremost scribes responsible for equipping our forces with Vantus runes. Do not think that your efforts as an artisan have gone unnoticed.\n\nWe noticed.\n\nI would like to present you with this technique. Now go, and use it to help us win this war.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43930] = { id = 43930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiends of Tel'anor" }
quests[43932] = { id = 43932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Oppression" }
quests[43933] = { id = 43933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Delas Moonfang", objectives = "Highlord, I am proud to begin the first steps of this new journey.\n\nThank you for taking me under your wing. I vow to follow the guiding principles - to act honorably, to uphold what is righteous, to fight against injustice, and to celebrate with my new brothers and sisters of the Silver Hand.\n\nUnder the Light, we stand as one!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43934] = { id = 43934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Path", description = "Highlord {name}, if I could have a moment of your time?\n\nLong have I followed the path of the Light, and for many years I studied under the Priestesses of the Moon. Yet, I have always felt my education incomplete, and a yearning to know more.\n\nWhen I walked into these halls, I finally felt a spark of what was missing. I believe that a new path lies before me.\n\nI wish to become a paladin of the Silver Hand. Will you allow me to join you?", progress = "What do you think?", completion = "Thank you, Highlord.", objectives = "Speak to Delas Moonfang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43935] = { id = 43935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Second Legend", description = "Perhaps it's time to consider improving your flexibility when it comes to powerful artifacts. There are still others that I think are worth pursuing if you are interested.\n\nLet me show you what your options are and you can choose one.", completion = "Excellent. You can begin as soon as you are ready.", objectives = "Choose a second artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43937] = { id = 43937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Refuge", description = "The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell.\n\nI believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar.\n\nIf you can convince the Nightfallen to aid us, they may be able to offer the Moon Guard and us both refuge right under the Legion's nose.", objectives = "Complete the \"Nightfall\" storyline in Suramar, then meet Archmage Kalec in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43938] = { id = 43938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Focusing Our Efforts", description = "The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell.\n\nI believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar.\n\nAfterward, seek out the Moon Guard in the northern reaches of Suramar. They, too, could be valuable allies in our cause... if they still oppose the Legion as they once did many years ago.", completion = "Let us speak with Thalrenus and discuss our plan of action.", objectives = "Complete the \"Nightfall\" and \"Moon Guard Stronghold\" storylines in Suramar, then meet Archmage Kalec in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43939] = { id = 43939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Chosen" }
