quests[43941] = { id = 43941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disc Chosen" }
quests[43942] = { id = 43942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timeworn Artifact", description = "<You've found a strange looking naga artifact on the fallen corpse.\nYou saw King Mrgl Mrgl as you were walking around Timeworn Strand. Maybe he knows what to do with it?>", completion = "Just what I've been looking for! <King Mrgl Mrgl studies the artifact> Ah! Yes. But there must be more of these Timeworn Artifacts still on the shore. Any more you can bring back would be greatly appreciated!", objectives = "Take the Timeworn Artifact to King Mrgl Mrgl nearby.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43943] = { id = 43943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Withered Army Training" }
quests[43945] = { id = 43945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expanding Your Horizons", description = "You are a fast study, {class}t {name}. The elements speak through you - it is rare to have such a connection to the world.\n\nA true shaman must walk many paths. For every role, one must have the right tools at hand. Only the most powerful weapons can lead us to victory against the Legion. Perhaps it is time to seek out another?\n\nSpeak with me and let us discuss your options.", completion = "Very well. Your allies have gathered here on the precipice - they will know how best to proceed.\n\nMay the winds be ever in your favor, Farseer.", objectives = "Speak with Aggra to choose a second artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43946] = { id = 43946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhancement Chosen" }
