quests[43948] = { id = 43948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoration Chosen" }
quests[43949] = { id = 43949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Weapons of Legend", description = "It is wise to carry more than one weapon to war. Sometimes one will be better suited than another. You should choose another weapon of legend to carry with you, especially against foes so deadly.\n\nWhat say you?", completion = "A powerful weapon for a powerful champion of the Halls. Let us begin.", objectives = "Choose a second artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
