quests[43957] = { id = 43957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jade Darkhaven" }
quests[43958] = { id = 43958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Body of Evidence", description = "There is an urgent matter that requires your attention, {name}.\n\nThe body of a woman with a knife in her back has turned up in the sewers.\n\nNormally, such a matter would be less than newsworthy... but this isn't your average cutthroat. It's an SI:7 operative!\n\nI've got some of our goons guarding the body, but you had better get over there before the word spreads.\n\nIf SI:7 finds out about this... it will be bad for business.", progress = "Did you identify the body? Was it an SI:7 operative?", completion = "So it's true? An SI:7 agent was assassinated in our own backyard?\n\nIf SI:7 links us to the murder, this will be bad for business. We'll need to get to the bottom of this sooner rather than later...", objectives = "Investigate the body of the SI:7 operative for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43959] = { id = 43959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stelleris Shakedown" }
quests[43960] = { id = 43960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cinderwing" }
quests[43961] = { id = 43961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestrix" }
quests[43962] = { id = 43962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blades of Destiny", description = "I'm glad that weapon you've been carrying around has proven useful. Our ally, the Lich King, has offered to provide you with a lead on another weapon should the one you already have somehow be lacking.\n\nConsider the options carefully and let me know which you would like to seek out.", completion = "Very well.", objectives = "Choose a second artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
