quests[43968] = { id = 43968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinchshank" }
quests[43969] = { id = 43969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hired Help", description = "I was fond of Margaux. News of her death weighs heavily on many of us.\n\n<Vanthir shakes his head sadly.>\n\nIf we are to carry on, we need to send a strong message. We need those like Durant to know that we are watching, and we will hold them accountable.\n\nI know someone who could help us.\n\nHis name is Arluin. To call him a reluctant ally would be generously overstating it. He is cautious, and will not risk himself without compensation.\n\nYou can find him in the alleys north of the Evermoon Bazaar.", progress = "Best not to lurk if you aren't doing business.", completion = "I will help you, but first I need you to do something for me.", objectives = "Locate Arluin and persuade him to help you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43970] = { id = 43970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewmaster Chosen" }
quests[43971] = { id = 43971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windwalker Chosen" }
quests[43972] = { id = 43972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistweaver Chosen" }
quests[43973] = { id = 43973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two Paths, Two Weapons", description = "We've searched through our scrolls and have found new leads on a couple of powerful weapons. They may prove beneficial in our efforts.\n\nHere, let me show you what I've found. If any of these interest you then simply let me know.", completion = "A wise choice.", objectives = "Choose a second artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
