quests[43975] = { id = 43975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruiting Shieldmaidens", description = "The powerful val'kyr Savyn Valorborn has arrived to aid us in bolstering our numbers. She ushers some of the most valorous vrykul shieldmaidens into the Halls of Valor.\n\nSpeak to her and recruit powerful troops to add to our roster.", completion = "I will rally the worthy in Odyn's name.", objectives = "Speak to Savyn Valorborn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
