quests[43980] = { id = 43980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Weapon of Old", description = "You have done well but our foes are powerful and cunning. It would be wise to be prepared for whatever they may unleash upon us. \n\nYou would be wise to consider obtaining another of the weapons of old to aid in our conflict.\n\nLet me know how you'd like to proceed.", completion = "A sound choice.", objectives = "Choose a second artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
