quests[43984] = { id = 43984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome Opens Again", description = "You've been doing well, friend, but you would be unstoppable if you had another weapon at your side.\n\nHere, let me show you what options remain in the book. If either of these interest you then simply let me know.", progress = "Thoughts, friend?", completion = "Yes, very good choice!", objectives = "Choose a second artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
