quests[43991] = { id = 43991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Protectors", description = "To fully unlock the powers of the Idol, we will need four manifestations of the wilds - an essence of ferocity, essence of regrowth, essence of balance, and essence of tenacity.\n\nTo find these essences, we must consult the protectors of the forest.\n\nGo to the Emerald Dreamway and call upon the powers of the ancient druidic stones. The protectors will only show themselves to those who can prove their connection to the wilds.", completion = "Did you sense the protectors of the wilds? Their presence is ever with us.", objectives = "Use your druidic powers to commune with protectors at the Feral Stone, the Guardian Stone, the Restoration Stone, and the Balance Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
