quests[44003] = { id = 44003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reef Lord Raj'his" }
quests[44004] = { id = 44004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringer of the Light", description = "Turalyon lives! For ages I had thought that my old friend had perished on some desolate Legion world. But to know that he yet lives and is in danger is too much to bear.\n\nWe must hurry, {name}. We must uncover the object's sacred purpose.\n\nThe prophet of whom Turalyon spoke of is undoubtedly the leader of the draenei, Velen. Take the object and journey to the Exodar. It is there that you will find Prophet Velen.\n\nI will open a portal for you now. Take my beacon and use it when you are ready to return.", progress = "Have you discovered anything about the object?", completion = "Kil'jaeden took the child from Velen, let Velen believe that the boy had been killed, then raised the child as an agent of the Burning Legion with the express purpose of murdering his own father? That bastard waited 13,000 years to exact vengeance upon Velen for defying Sargeras and the Legion? The Deceiver indeed...\n\nFor Velen to have to experience such tragedy after what he and his people have already been through is heartbreaking. Such a thing would test anyone's faith.", objectives = "Discover the purpose of the Mysterious Lightbound Object.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44005] = { id = 44005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Reaction to Warrior Artifacts" }
quests[44006] = { id = 44006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Fullest Potential", description = "I see that you walk many paths, as a true shaman should.\n\nTwo mighty artifacts are already in your possession. To seek a third would not be greed: it would be the fulfillment of your destiny, the completion of a circle.\n\nSpeak with me, and together we will unlock your fullest potential.", progress = "Where are the spirits guiding you, Farseer?", completion = "The path ahead is clear. Your allies await you on this ledge. May the spirits walk with you, Farseer!", objectives = "Speak with Aggra to choose a third artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44009] = { id = 44009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Falling Star", description = "{class}t {name}, thank you for coming. I have a matter of some urgency that requires your unique talents.\n\nThe Order of the Silver Hand have reported that an extraordinarily luminescent object has emerged from the Felstorm and is currently falling towards the coast of Suramar. What I find most curious about this occurrence is that the object was reported as having \"cut a swath\" through the Felstorm itself.\n\nWill you investigate? There is a gryphon awaiting your arrival at Krasus' Landing.", progress = "Show me what you've found.", completion = "Most curious indeed! This is no object of the Legion's making. Let me have a closer look.", objectives = "Find the Mysterious Lightbound Object.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44010] = { id = 44010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Oreth the Vile" }
