quests[44034] = { id = 44034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Worthy Blade", description = "We still have plans prepared to obtain other weapons of incredible power - tools that you may find useful to have on hand as you continue your work.\n\nI would be happy to go over the remaining options with you so that you may make an informed decision.", completion = "Yes, I think that will do rather nicely as well.\n\nGood choice.", objectives = "Choose a second artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
