quests[44039] = { id = 44039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea King Tidross" }
quests[44040] = { id = 44040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vote of Confidence", description = "I will endeavor to protect my son until the votes are cast.\n\nCoryn Stelleris is a predator even among the nobility. It does not surprise me that he should stoop to such depths to ensure his own success.\n\nTell Ly'leth that she has my support. Unequivocally.\n\nYou may also choose to tell her that Coryn Stelleris will hurt her, if she gives him a chance.\n\nBe careful.", completion = "I know of Coryn. We will not underestimate his venom, rest assured.\n\nThank you for helping Aurore. She is a dear friend of mine.", objectives = "Return to Ly'leth at the Waning Crescent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44041] = { id = 44041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloody Truth", description = "We need to find out who is behind the assassination of Amber Kearnen.\n\nIt won't be long before SI:7 realizes that their agent is MIA and comes sniffing around The Hall of Shadows.\n\nHere, take these stylish spy glasses and set them to scan for traces of hemoglobin. I've taken the liberty of calibrating them specifically for Amber Kearnen's blood.\n\nFollow the blood trail back to the culprits, but make sure to stay out of sight!\n\nReport back to us when you've got the information we need.", progress = "Were you able to find out who's behind the assassination attempt?", completion = "Let me get this straight...\n\nYou are saying that Master Mathias Shaw ordered the death of one of his best agents? This is far more serious than I first thought.\n\nWe'll need to continue the search for clues...", objectives = "Discover the truth behind the hit on the SI:7 agent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44043] = { id = 44043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continuing the Legend", description = "There are still two paths you may walk - two powerful weapons you might yet obtain to aid you in the fight against the Legion.\n\nI will help you recall your remaining options, of course.", completion = "A wise path to follow - may it take you far.", objectives = "Choose a second artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44044] = { id = 44044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felled Experiment" }
