quests[44074] = { id = 44074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair: Essence of Tenacity", description = "Greetings, Archdruid. I hear that you seek the essence of tenacity.\n\nThere is none more unyielding and unbreakable than a creature of stone.\n\nIn Neltharion's Lair is a monster known as Rokmora. Slay him, and draw from him the essence that you need.", progress = "Stand firm, {class}.", completion = "Thank you, Archdruid.", objectives = "Collect 1 Essence of Tenacity from Rokmora in Neltharion's Lair, then slay Dar'grul the Underking.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44075] = { id = 44075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: Essence of Ferocity", description = "To find the essence of ferocity, you must seek a creature who has slain thousands, and is revered by even the gods.\n\nI speak of none other than the wolf, Fenryr, whom you can find hunting in the eternal forests of the Halls of Valor.", progress = "It takes a ferocious beast to take down another ferocious beast.", completion = "Excellent, Arch {class}.", objectives = "Collect 1 Essence of Ferocity from Fenryr in the Halls of Valor, then prove your worth to Odyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44076] = { id = 44076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkheart Thicket: Essence of Regrowth", description = "My child, I can think of only one place to capture the essence of regrowth.\n\nDeep within Darkheart Thicket is Oakheart, a loyal ancient defender of the grove. He has recently fallen to the Nightmare's corruption, but deep within his heart, he still fights.\n\nGather the essence of this great tree, so that his everliving soul may be used to fuel new life.", progress = "My heart aches for those fallen to the Nightmare.", completion = "I am sad to hear of Oakheart's demise, but his soul will live on.", objectives = "Collect 1 Essence of Regrowth from Oakheart in Darkheart Thicket, then defeat the Shade of Xavius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44077] = { id = 44077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: Essence of Balance", description = "Within the Eye of Azshara in Azsuna, a powerful being known as the Wrath of Azshara grows in strength. It is a blasphemy of nature - an infusion of stolen arcane power, and cannot be allowed to exist.\n\nSlay it. In its aftermath, you may find the essence of balance that you seek.", progress = "We follow Elune's path.", completion = "Wonderful. This is exactly what we need.", objectives = "Collect 1 Essence of Balance from the Wrath of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44078] = { id = 44078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supporting Cast" }
quests[44079] = { id = 44079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druids of the Scythe - 1" }
quests[44080] = { id = 44080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friend of the Animals" }
quests[44081] = { id = 44081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treacherous Leyrunners" }
quests[44082] = { id = 44082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knights of the Ebon Blade", description = "Korgaz Deadaxe has arrived at Acherus to aid us in recruiting additional death knights. He has an eye for potential.\n\nI cannot emphasize enough that it is of the utmost importance that we replenish our numbers during the battle with the Burning Legion.\n\nThe demon armies are nearly endless and we are few.\n\nSpeak with Korgaz when you are ready to recruit additional death knights.", completion = "Greetings, Deathlord. It is an honor to serve you.\n\nI have been keeping an eye on the casualties of the Alliance and Horde upon the battlefield. Supply is limited, but there are some very promising prospects...", objectives = "Speak to Korgaz Deadaxe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44083] = { id = 44083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimoire of the First Necrolyte", description = "This ancient tome appears to be the spellbook of Sataiel, the first necrolyte.\n\nWithin its pages of curses and cantrips, you discover instructions for a ritual that Sataiel was concocting to empower Ulthalesh, the Deadwind Harvester. She calls this ritual, \"The Rite of the Executioner.\"\n\nThe site was chosen and prepared, but Sataiel met her unfortunate end before she could proceed.  Perhaps you can pick up where she left off?\n\nFirst, you'll need some skulls.", progress = "There's just enough room on the altar for the bounty of skulls you've collected.", completion = "The altar is coated with hundreds of years of dust, but the candles somehow still glow in the distance.\n\nThis must be the site for the ritual.", objectives = "Collect 13 Skulls of the Executed from powerful humanoid champions throughout Broken Isles, and bring them to the Executioner's Altar in the crypt near Morgan's Plot in Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44084] = { id = 44084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for Margaux", description = "<Sylverin sputters, pale-faced with rage.>\n\nHow could they? Margaux did everything they asked of her and more! The arcwine never stopped flowing despite everything they did to us! To her!\n\nSuch injustice cannot stand. We must take vengeance for Margaux.", completion = "<Thalyssra is speechless for a moment.>", objectives = "Slay 8 Vineyard Enforcers or Wardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44085] = { id = 44085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Affliction Chosen" }
quests[44086] = { id = 44086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destruction Chosen" }
quests[44087] = { id = 44087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Fel Hammer", description = "{name}, Battlelord Gaardoun asked me to retrieve you. He says there is a very important matter that he needs your help with.\n\nHe requests your presence back on the Fel Hammer as soon as possible.", completion = "Commander. I am glad to see that Asha was able to find you so quickly.\n\nThere is something important that you must attend to as soon as possible.", objectives = "Speak with Battlelord Gaardoun on the Fel Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44088] = { id = 44088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonology Chosen" }
quests[44089] = { id = 44089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Greater Arsenal", description = "The tome speaks of one more weapon that friend can use against our foes. \n\nDo you wish to seek it?", progress = "Have you made your choice?", completion = "Friend is very wise! You can never have too many weapons!", objectives = "Speak with Calydus to choose to pursue your final artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44090] = { id = 44090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pledge of Loyalty", description = "The eagle appears to have a message for you:\n\n\n\nI hope this message finds you well.\n\nWord of Ohn'ahra's omen has traveled fast. There are many who wish to pledge their loyalty to the Unseen Path's new leader.\n\nReturn to me at Trueshot Lodge, and we can discuss this further.\n\n-Altar Keeper Biehn", completion = "I see you received my message.", objectives = "Return to Altar Keeper Biehn in Trueshot Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44091] = { id = 44091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Needs of the Many", description = "You've seen that the Legion is everywhere. Even with the Illidari as your allies, we are at a great disadvantage.\n\nWe need an edge against the Legion... something to send them back to the Nether.\n\nWe have heard that Dalaran will be the focal point of our campaign. I suggest you go there. You must do anything necessary to become stronger. ANYTHING.\n\nI have seen Kirin Tor mages near Grommash Hold. They can send you to Dalaran.\n\nGo. Take revenge upon the Legion!", objectives = "Seek out the Kirin Tor mages in Orgrimmar and travel to Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44092] = { id = 44092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protect the Home Front", description = "The Legion hasn't just invaded this city. Their evil is spreading across Azeroth, threatening the far corners of our world.\n\nWe must seek them out and stop them, everywhere their darkness touches.\n\nWe've dispatched scouts around the world to watch for Legion activity. As invasions arise, we'll mark the locations on your map.\n\nMake them suffer, {name}!", progress = "Find them! Stop them! Suffer well!", completion = "You've done it! You've broken an invasion!\n\nIf only that had ended our campaign. But the Legion will never relent until they are destroyed... or have destroyed us.\n\nDon't let up! Fight off more of these wretched invasions, {name}. The wyrmtongue we're holding captive here will reward your efforts.", objectives = "Open your map to find an active Legion invasion in Kalimdor or Eastern Kingdoms. Go to the invasion site and stop the demons!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44093] = { id = 44093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head 1 Looted" }
quests[44094] = { id = 44094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head 2 Looted" }
quests[44095] = { id = 44095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head 3 Looted" }
quests[44096] = { id = 44096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head 4 Looted" }
quests[44097] = { id = 44097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head 5 Looted" }
quests[44098] = { id = 44098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruiting Apprentices", description = "Grand Conjuror Mimic has arrived to aid us in bolstering our numbers. She seeks out the most promising apprentices and trains them very quickly. Her former students are some of the most powerful conjurors in the land!\n\nSpeak to her and recruit some of her apprentices to add to our roster.", completion = "Good to see you, {name}. My apprentices are learning rapidly and are ready to serve you.", objectives = "Speak to Grand Conjuror Mimic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44099] = { id = 44099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mutual Friend", description = "It's good to see you are well.\n\nI've been sent by our mutual friend, Calydus. He is eager to speak with you.\n\nPlease return to Dreadscar Rift at your earliest convenience.", completion = "It's so good to see friend once again.", objectives = "Return to Calydus within Dreadscar Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44100] = { id = 44100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proper Introductions", description = "I'm glad I found you. \n\nI have a message from Alonsus Faol.\n\nHe says introductions are in order, and requests your presence within Netherlight Temple at your earliest convenience.", completion = "I see you received my message.", objectives = "Return to Alonsus Faol within Netherlight Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44101] = { id = 44101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply Dropped", description = "These supplies for the Earthen Ring have not been processed yet. It looks like someone has been rummaging through them and looting whatever can be carried. You have reasons to suspect the Grimtotem tribe, on account of the fact that one of their champions is nearby, visibly pilfering your stuff.\n\nChallenge the Grimtotem to secure your resources!", progress = "<The Grimtotem Champion snorts derisively at you.>", completion = "Very well, I yield - I yield!\n\nCurse you, {class}, and that weapon of yours. Without it the Grimtotem would've been victorious.\n\nTake your lousy supplies. But we will be back!", objectives = "Challenge and defeat the Grimtotem Champion who is raiding your supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44102] = { id = 44102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 043 - Grey Shoals" }
quests[44103] = { id = 44103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 044 - Felblaze Underwater" }
quests[44104] = { id = 44104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 045 - Ley Ruins 02" }
quests[44105] = { id = 44105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 046 - Temple of a Thousand Lights" }
quests[44106] = { id = 44106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archdruid of Lore", description = "Elothir resides in the ancient grove Thas'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore.\n\nSeek him out and tell him that he is desperately needed here.", completion = "Welcome, {name}. News of your heroism spreads from the Dreamgrove.", objectives = "Seek out Elothir in Thas'talah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44108] = { id = 44108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ragemaw" }
quests[44112] = { id = 44112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading for Dreams", description = "From the look of you, I take it you're an alchemist, yes?\n\nI'd be willing to trade my services with you for a price that I deem is fair.\n\nI have been away from Suramar for some time now. I long for an Ysera's Dream Draught. To concoct it, you'll need some dreamleaf as well as the leaves of a Dreamer's Tear.\n\nOne grows not to far from here in the clearing of some ruins. Take my flask, make this drink for me, and I'll do as you ask.", progress = "<Leyweaver Erenyi seems lost in thought.>", completion = "You've crafted this rather well. I'm slightly impressed.\n\nNow let me see that silk of yours...", objectives = "Use the Nightborne Flask to craft an Ysera's Dream Draught.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44113] = { id = 44113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Achronos" }
quests[44114] = { id = 44114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Magistrix Vilessa" }
quests[44115] = { id = 44115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Legion!", description = "Welcome to World of Warcraft: Legion! We hope you enjoy all of the new experiences that await you in the Broken Isles, and want to make sure you're well-armed to take on the Burning Legion." }
quests[44116] = { id = 44116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery at Citrine Bay", description = "The Burning Legion invades Azeroth, and SI:7 is wasting valuable resources hunting down and assassinating one of their top agents?\n\nSomething isn't adding up...\n\nWe need to find out how deep this goes. Why was Amber Kearnen being hunted by her own organization?\n\nThe encrypted letter she was carrying may hold the clues... but we need more information.\n\nThe SI:7 assassins you tailed in Dalaran mentioned Citrine Bay... search Citrine Bay for clues and we'll see about getting this letter decrypted.", completion = "Ye had best keep ye voice below whispers, matey... thar be a band 'o pirates ahead! Fer sure, these be not th' type ye want to mess around wit'...", objectives = "Speak with Fleet Admiral Tethys at Citrine Bay in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44117] = { id = 44117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Flies When Yer Havin' Rum!", description = "Thar be few pirates ye want to cross swords wit' less than th' Red Blade! They be salty dogs, indeed!\n\nThat being said... they does have a way wit' rum! I'll level wit' ye, {name}... thar be few rums as jolly as that 'o th' Red Blade.\n\nSeein' as ye be headin' off in search 'o clues, ye might as well brin' back a few bottles while ye be at it!\n\nBrin' me back as many bottles as ye can find, and I'll reward ye handsomely! Pirates honor, {name}!", progress = "Have ye got th' spiced rum, {name}?", completion = "<Fleet Admiral Tethys pops the cork from a bottle and takes a long gulp.>\n\nAye, 'tis be th' stuff, {name}. Ye've done well!", objectives = "Collect 10 bottles of Red Blade Rum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44118] = { id = 44118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Auditor Esiel" }
quests[44119] = { id = 44119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Volshax, Breaker of Will" }
quests[44120] = { id = 44120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari Allies", description = "At first I was unsure whether it was wise to allow the Illidari inside the city. But they may have just saved all our lives.\n\nI gave the demon hunters leave to establish a temporary camp in the Mage Quarter. I'd like you to be my personal envoy to them. Thank the Illidari for their assistance and see how they can aid our cause.\n\nJust... keep your eyes open. They have harnessed a terrible power, and we must be ready should they be consumed by the darkness within.", completion = "I see by the blood spatters that Jace revealed the demons to you. I trust the young king is safe.\n\nWe have more work ahead of us, {class}. Much more.", objectives = "Meet with the Illidari representative in the Mage Quarter of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44121] = { id = 44121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Az'jatar" }
