quests[44136] = { id = 44136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 056 - The Undergorge - zto" }
quests[44137] = { id = 44137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Fray", description = "The Burning Legion has beaten us here, but so too have the Illidari. It looks like the demon hunters are holding their own, but just barely.\n\nCome, let's put that weapon of yours to use. I'll figure out our next move while you crush the Legion.", completion = "You are a most welcome sight, {name}. And, you brought considerable firepower in the form of Archmage Khadgar.\n\nMalevolence has been portaling us back and forth between here and the Fel Hammer. We pushed the demons out of these ruins, but they are stronger than any we have encountered before.\n\nYour leadership is greatly appreciated. If we do not crush this Legion invasion now, they will overrun Azsuna and then the rest of the Broken Isles.", objectives = "Speak with the lead demon hunter at Illidari Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44138] = { id = 44138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 057 - Kel'delar - ZTO" }
quests[44139] = { id = 44139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 058 - Dreadroot - zto" }
quests[44140] = { id = 44140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Within", description = "Our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within.\n\nI haven't heard from them in a while.\n\nIt would be best if you could find and lead them to success. Agreed?", completion = "Oh, {name}, it's you. Good, we've got a little problem here.\n\nKayn didn't think that Cyana and I could handle this on our own? He might have been right this time.", objectives = "Find Kor'vas Bloodthorn on Faronaar at Vanquish Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44141] = { id = 44141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
