quests[44150] = { id = 44150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[44151] = { id = 44151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[44152] = { id = 44152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Growing Crisis", description = "The Arcan'dor is failing.\n\nThis energy was once bound in its boughs and fueled its growth. There was balance, between life and arcane.\n\nNow that energy is breaking free. When the heart can no longer hold it, this tree will kill every living thing in this hall.\n\nI have seen this happen before and I must find a way to stop it from happening again. \n\nWe must go to the tree that came before. Its bones can guide us.\n\nMeet me at the temple of Fal'adora. We will descend together.", completion = "I must find a way...", objectives = "Meet Valewalker Farodin at the Temple of Fala'dora. You can travel there using the Portal to Falanaar in Shal'aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44153] = { id = 44153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light's Charge", description = "\"You did not ask for this burden, but it is what fate has deemed.\" Turalyon's haunting last words still echo in my mind. I worry about the fate of the draenei... about the fate of my friend, Velen; but we must remain vigilant, {name}!\n\nFor now, Light's Heart remains under your watchful eye. There is one place on Azeroth that I would trust with the safekeeping of the object: your order hall. Take it there, {name}. I will remain in Dalaran and continue looking for answers. There must be another way!", progress = "This is where you must place Light's Heart.", completion = "<A force within Light's Heart activates as you lay it down.>\n\n<You feel hopeful.>", objectives = "Place Light's Heart in your Order Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44154] = { id = 44154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rite of the Executioner", description = "The skulls have been gathered and the ritual area is prepared.\n\nAll that is left is to perform the incantation, and Ulthalesh will become imbued with the essence of the Executioner.", objectives = "Interact with the Pile of Skulls and complete the Rite of the Executioner in the crypt near Morgan's Plot in Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44155] = { id = 44155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching For Clues", description = "It be no coincidence that we be in Citrine Bay investigatin' a murder, and we find th' band 'o pirates known as th' Red Blade here as well!\n\nAye, this be no coincidence at all, {name}... but we be needin' proof!\n\nYe go on ahead and look fer clues and I'll find some scallywags to interrogate.\n\nAye {name}, we'll get t' 'th bottom o' this t' be sure! Thar be no doubt!", progress = "Have ye found evidence 'o th' murder from th' pirates 'o th' Red Blade?", completion = "Aye, what do ye have thar? 'tis be a letter from Master Mathias Shaw himself! Writ' to th' Red Blade no less.\n\nAye, it be just as I thought... these orders be fishier than a bucket 'o chum!", objectives = "Find proof of SI:7 working with The Red Blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44156] = { id = 44156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Arcan'dor Closes...", description = "I hope you have a better understanding of what is at stake.\n\nCome. There is no more for us to do here.\n\nMeet me in Shal'aran and we will discuss what steps we may take next.", completion = "We must find a solution. We are running out of time.", objectives = "Return to Shal'aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44157] = { id = 44157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Withered Wrangling: Tel'anor" }
quests[44158] = { id = 44158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Withered Wrangling: Falanaar" }
quests[44159] = { id = 44159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ticket for Marin", description = "This Vault Ticket should be delivered to Marin Noggenfogger.", progress = "Another {class} shows up with another ticket to take more of my loot. Make your choice.", completion = "Have at it, {name}. Make your choice.", objectives = "Deliver the Vault Ticket to Marin Noggenfogger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44161] = { id = 44161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Things Gaardoun Needs", description = "Battlelord Gaardoun has offered to recruit more broken warriors for the cause. He just needs a few things first. He said something about the right tool for the job, or something like that.\n\nTime to put your new champions to the test. I'm sure it will be a grueling mission.", progress = "Did they come back already with whatever it is that Gaardoun needs?", completion = "Well, at least we're going to have some fresh faces around here. If a broken's face can ever be called fresh, that is.\n\n<Kor'vas smirks.>", objectives = "Use the Scouting Map and complete the mission, \"Things Gaardoun Needs\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44164] = { id = 44164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Burning Path Through Time", description = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", progress = "I foresee that you will follow the blazing star, and walk the paths it reveals.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44166] = { id = 44166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Frozen Path Through Time", description = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", progress = "I foresee that you will follow the chill star, and walk the paths it reveals.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44167] = { id = 44167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shattered Path Through Time", description = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", progress = "I foresee that you will follow the Destroyer's star, and walk the paths it reveals.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44171] = { id = 44171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of War", description = "When the sign of the warrior shines in the night sky, fortune favors the daring. Powerful foes may yield even greater rewards. Venture deep into caverns and strongholds to prove your worth.", completion = "Well done, {name}. I knew you could do it.", objectives = "Complete 4 dungeons on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44172] = { id = 44172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arena Calls", description = "This alignment of the stars is a dire sign, stirring bloodlust and calling warriors to battle to the death in close quarters. Arena masters turn a tidy profit during these days, likely not understanding why their stands are overflowing. Amidst the excitement, great rewards do await those brave, or foolhardy, enough to venture into the arena....", completion = "Well done, {name}. I knew you would do it.", objectives = "Win 10 Arena Skirmish battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44173] = { id = 44173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Battle", description = "The favorite star of warlords and generals dominates the sky, offering good fortune to tacticians everywhere. Some say that the battle star hones the instincts of commanders to the point of near-prophecy. If ever you were going to test yourself on the field of battle, now is the time.", progress = "I foresee battle in your future, {name}. And flags, for some reason.", completion = "I trust your battles went well. And that's not just a turn of phrase. I know they did. I knew they would.", objectives = "Win 4 Battleground matches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44174] = { id = 44174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Very Best", description = "This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.", progress = "I foresee that you will travel across the land, searching far and wide. It's your destiny.", completion = "Well done, {name}. With courage, you have faced every challenge along the way, and battled every day to claim your rightful place.", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44175] = { id = 44175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Awaits", description = "When the sign of the emissary shines in the night sky, the stars strengthen existing bonds and forge new ones. Friendship is still not cheaply won, and deeds will prove loyalty, but trust comes more readily during these days. Venture across the Broken Isles, and give aid where you may, to prove your worth.", progress = "I foresee that you will win many friends this week.", completion = "Well done, {name}.", objectives = "Complete 20 World Quests in the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44176] = { id = 44176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conveniences of Home", description = "This chest could prove very useful to our efforts. Take the chest back to Shal'aran.", completion = "The heavy chest offers plenty of room to carry all of your belongings.", objectives = "Take the Traveler's Banking Chest to Shal'aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44177] = { id = 44177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Secrets and Shady Deals", description = "Whatever Amber Kearnen knew, Mathias Shaw didn't want it gettin' out...\n\nAye, this be dirty business indeed, hiring th' Red Blade at such a price... just to hunt down and kill one of their own!\n\nYe best get back to th' Hall 'o Shadows, and let Lord Ravenholdt know what we found here in Citrine Bay.\n\nWhatever SI:7 be up to, it be goin' deeper than we first imagined...", completion = "SI:7 made a secret deal with The Red Blade to hunt down Amber Kearnen?\n\nIt seems that Master Mathias Shaw was willing to pay any cost to have her dealt with...", objectives = "Speak with Lord Ravenholdt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44178] = { id = 44178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Particularly Potent Potion", description = "I've got a proposition for ya, {name}!\n\nWord has it that Trade Prince Gallywix recently acquired a priceless, one-of-a-kind love potion. There's only one goblin who can replicate it and you're looking at him! Get me that potion and I can make us both richer than kings!\n\nThe pleasure palace is located in Azshara and it has been on high alert since the war started. Gallywix isn't letting anybody in except his personal staff, but I know a girl on the inside!\n\nFind her and she'll get you to the safe!", progress = "Do you have the goods?", completion = "Aww, yesss! That's the stuff!\n\n<Noggenfogger pops the cork and dabs some of the potion on his finger.>\n\nHave mercy! WOWZA! I'm going to need some time alone with this stuff!", objectives = "Steal Love Potion #6 from Gallywix's personal safe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44179] = { id = 44179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure", description = "There is a strange energy in the air.\n\nI feel as if a force is growing, pressing down on us. It is worrisome.\n\nValtrois works most closely with the sources of power in this room.\n\nSpeak to her. Ask if there is anything to be concerned with.", sourceObjective = "Speak with Valtrois.", sourceObjectiveStatus = "unverified-source-field" }
quests[44180] = { id = 44180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Marin Noggenfogger", objectives = "Look, {name}. I'll level with ya...\n\nWithout your thieving prowess I'd be a much poorer goblin than I am today. I think we should keep this gold-en partnership going!\n\nYou scratch my back, I'll scratch yours. Together, we'll put an end to this Burning Legion invasion and line our pockets with all the wealth in Azeroth!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44181] = { id = 44181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Fleet Admiral Tethys", objectives = "Aye, matey! We've had some good voyages together! Blood was spilt, rum was drank, n' our search fer clues was a success!\n\nI'll level wit' ye, {name}. I be not havin' such an adventure in some years now. Sailin' wit' ye felt like early mornin' on th' poop deck when th' salty ocean rum splashes ye wide awake!\n\nHow abouts I come aboard n' join yer crew as first matey?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44182] = { id = 44182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "City Under Siege", description = "<Khadgar's voice erupts from the elemental once again.>\n\nObtaining information on the Pillars of Creation before the Legion could stop us was a considerable victory. It won't bring back those we lost on the Broken Shore, but I believe it will help us avenge them.\n\nDalaran has become a focal point of the Legion's assault. Your presence here is crucial. If the demons are putting this much effort into attacking the city, it means Dalaran will play a pivotal role in the struggle to save Azeroth.", completion = "I shored up Karazhan's defenses as best I could, but I have little confidence they'll hold. We have other matters to focus on in any case.\n\nGul'dan has set his demon dogs loose upon Dalaran. He wants this city gone... but we're not going to let him have his way.\n\nI believe Dalaran will become the focal point of our campaign against the Legion, neutral ground where the heroes of every kingdom can join together against our mutual foe.\n\nLet's get to work, {name}.", objectives = "Meet Khadgar at the Chamber of the Guardian in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44183] = { id = 44183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lord Jorach Ravenholdt", objectives = "This is a dangerous mystery we've stumbled upon, {name}. It would not be fair for me to stand idly by as you risk your life to uncover this corruption.\n\nAfter all, without honor and brotherhood among thieves, none of us will stand to profit!\n\nFrom this point on, I'll pledge my personal services against the threat of the Burning Legion and the dark mystery we are unraveling. My blade is yours, {name}...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44184] = { id = 44184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Blink of an Eye", description = "The Broken Isles is our destination, {name}.\n\nThe spell that will blink Dalaran to its new location is not a simple one. It will take this Council's full energy and attention.\n\nAs Jaina is... absent, Kalecgos of the blue dragonflight has offered us his aid.\n\nThe Legion will make every attempt to stop us, but we will not falter. It is time to begin!", completion = "Ah, {name}, it's good to see you on your feet! The members of the Council of Six are recuperating from their ordeal.\n\nThe intensity of the teleportation spell can be disorienting. It seems you lost consciousness for a time, but at least you didn't awaken to find yourself stuck in a wall!\n\nDalaran has been relocated to the Broken Isles. From here, we will spearhead the effort to acquire the Pillars of Creation and drive the Legion from Azeroth once and for all!", objectives = "Witness the teleportation of Dalaran to the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44185] = { id = 44185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Sanaar" }
quests[44186] = { id = 44186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Broodmother Shu'malis" }
quests[44187] = { id = 44187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Cinderwing" }
