quests[44195] = { id = 44195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Workorders for Armaments", description = "I can get you the best deals on some slightly... used... equipment.", progress = "Place a workorder for a shipment of Champion Armaments and Equipment.", completion = "The orders been sent, my people are on the case.  Check back soon and you can pickup the shipment right here." }
